    """
    Bookings that were paid before commissions existed get the split they would have had at the default 10%:
    paid, shoot not done -> held; completed -> ready to pay; cancelled with a refund -> what is left.
    """
    Booking = apps.get_model("photopholio", "Booking")
    Payment = apps.get_model("photopholio", "Payment")
    percent = 10
    for booking in Booking.objects.select_related("photographer").all():
        payment = Payment.objects.filter(booking=booking, status="completed").order_by("-payment_date").first()
        if payment is None:
            continue
        kept = payment.amount - payment.refund_amount
        service = booking.price if booking.price is not None else booking.photographer.price_per_day
        if kept > 0 and payment.amount > 0:
            fee = (kept * min(service, payment.amount) // payment.amount) * percent // 100
        else:
            fee = 0
        payout = max(kept - fee, 0)
        if booking.status == "completed":
            status = "ready"
        elif booking.status == "confirmed":
            status = "held"
        else:
            status = "ready" if payout > 0 else "void"
        Booking.objects.filter(pk=booking.pk).update(commission_percent=percent, platform_fee=fee,
                                                     payout_amount=payout, payout_status=status)


